#include "lsmash.h"
#include <stdio.h>
int main(int argc,char**argv){if(argc!=2)return 2;lsmash_root_t*r=lsmash_create_root();lsmash_file_parameters_t f;if(!r||lsmash_open_file(argv[1],1,&f)<0)return 3;lsmash_file_t*h=lsmash_set_file(r,&f);if(!h||lsmash_read_file(h,&f)<0)return 4;lsmash_movie_parameters_t m;lsmash_initialize_movie_parameters(&m);if(lsmash_get_movie_parameters(r,&m))return 5;printf("movie tracks=%u timescale=%u\n",m.number_of_tracks,m.timescale);if(m.number_of_tracks!=2)return 6;for(unsigned i=1;i<=2;i++){unsigned t=lsmash_get_track_ID(r,i);if(lsmash_construct_timeline(r,t))return 7;unsigned n=lsmash_get_sample_count_in_media_timeline(r,t);lsmash_sample_t*s=lsmash_get_sample_from_media_timeline(r,t,1);if(!s||!n||!s->length)return 8;printf("track=%u samples=%u first_bytes=%u edits=%u\n",t,n,s->length,lsmash_count_explicit_timeline_map(r,t));lsmash_delete_sample(s);}lsmash_destroy_root(r);lsmash_close_file(&f);return 0;}
